import { orbRuntimeFactory, Runtime } from './runtime.js';

const EXPORT_KEYS = ['colorA', 'colorB', 'colorC', 'speed', 'react', 'glow', 'detail', 'scale', 'introDuration'];

export function cleanConfig(config) {
  const out = {};
  for (const k of EXPORT_KEYS) if (config[k] !== undefined) out[k] = config[k];
  return out;
}

/** Standalone, dependency-free file: works as <script src> or <script type="module">. */
export function buildComponentFile(def, config) {
  const orb = { id: def.id, name: def.name, frag: def.frag };
  return `/*!
 * AI Orb · ${def.name}
 * Generated by AI Orbs Gallery — https://github.com/neybarao/ai-orbs-gallery
 * WebGL2 · no dependencies
 *
 * <ai-orb state="idle"></ai-orb>
 * states: intro | idle | speaking | transition | thinking | auto
 */
(function () {
  var AiOrb = (${orbRuntimeFactory.toString()})(globalThis);
  AiOrb.registerOrb(${JSON.stringify(orb)}, ${JSON.stringify(cleanConfig(config))});
  AiOrb.defineElement('ai-orb');
  globalThis.AiOrb = AiOrb;
})();
`;
}

export function fileName(def) {
  return `ai-orb-${def.id}.js`;
}

export function snippets(def, config) {
  const f = fileName(def);
  return {
    html: `<script src="./${f}"></script>

<ai-orb orb="${def.id}" state="intro"
  style="width:240px;height:240px"></ai-orb>

<script>
  const orb = document.querySelector('ai-orb');
  // orb.state = 'thinking';
  // orb.useMicrophone();              // react to the mic
  // orb.connectAudioElement(ttsAudio); // react to your TTS
</script>`,
    react: `import { useEffect, useRef } from 'react';
import './${f}';

export function Orb({ state = 'idle', size = 240, stream, audioEl }) {
  const ref = useRef(null);
  useEffect(() => { ref.current.state = state; }, [state]);
  useEffect(() => { if (stream) ref.current.connectStream(stream); }, [stream]);
  useEffect(() => { if (audioEl) ref.current.connectAudioElement(audioEl); }, [audioEl]);
  return <ai-orb ref={ref} orb="${def.id}"
    style={{ width: size, height: size, display: 'block' }} />;
}`,
    api: `const orb = document.querySelector('ai-orb');

// states
orb.state = 'intro' | 'idle' | 'speaking'
          | 'transition' | 'thinking' | 'auto';
orb.replayIntro();

// audio sources
await orb.useMicrophone();
await orb.useSystemAudio();        // desktop Chromium
await orb.connectStream(stream);   // e.g. WebRTC remote
await orb.connectAudioElement(el); // <audio>/<video>
orb.setLevel(0.6);                 // drive manually
orb.setLevel(null);                // release
orb.stopAudio();

// look
orb.config = ${JSON.stringify(cleanConfig(config))};`,
  };
}

export function buildDemoHtml(def, config) {
  const js = buildComponentFile(def, config).replace(/<\/script/gi, '<\\/script');
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AI Orb · ${def.name}</title>
<style>
  html,body{margin:0;height:100%;background:#000;color:#ddd;font:14px system-ui,sans-serif}
  body{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px}
  ai-orb{width:min(70vmin,480px);height:min(70vmin,480px)}
  .bar{display:flex;gap:6px;flex-wrap:wrap;justify-content:center}
  button{background:#111;border:1px solid #333;color:#ddd;border-radius:999px;padding:7px 14px;cursor:pointer}
</style></head><body>
<ai-orb orb="${def.id}" state="intro"></ai-orb>
<div class="bar">
  <button data-s="intro">intro</button><button data-s="idle">idle</button><button data-s="speaking">speaking</button>
  <button data-s="transition">transition</button><button data-s="thinking">thinking</button><button data-s="auto">auto</button>
  <button id="mic">use mic</button>
</div>
<script>${js}</script>
<script>
  const orb = document.querySelector('ai-orb');
  document.querySelectorAll('[data-s]').forEach(b => b.onclick = () => { orb.state = b.dataset.s; if (b.dataset.s === 'intro') orb.replayIntro(); });
  document.getElementById('mic').onclick = () => orb.useMicrophone().then(() => orb.state = 'auto').catch(e => alert(e.message));
</script>
</body></html>`;
}

export function download(name, content, type = 'text/plain') {
  const blob = content instanceof Blob ? content : new Blob([content], { type });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

// ---------------------------------------------------------------- video
export function videoFormats(transparent) {
  const list = [
    { id: 'mp4', label: 'MP4', mimes: ['video/mp4;codecs=avc1.42E01E', 'video/mp4;codecs=avc1', 'video/mp4'] },
    { id: 'webm', label: 'WebM', mimes: ['video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm'] },
  ];
  const ok = typeof MediaRecorder !== 'undefined';
  return list
    .filter((f) => !transparent || f.id === 'webm')
    .map((f) => ({ ...f, mime: ok ? f.mimes.find((m) => MediaRecorder.isTypeSupported(m)) : undefined }))
    .filter((f) => f.mime);
}

/**
 * Records `duration` seconds of an orb state in real time.
 * live: optional AudioReactor (null = simulated voice)
 */
export function recordVideo({ def, config, state, duration, size, fps, format, background, transparent, live, onProgress }) {
  return new Promise((resolve, reject) => {
    const fmt = videoFormats(transparent).find((f) => f.id === format) || videoFormats(transparent)[0];
    if (!fmt) { reject(new Error('Video recording is not supported in this browser.')); return; }
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = size;
    let renderer;
    try { renderer = new Runtime.OrbRenderer(canvas, { powerPreference: 'high-performance' }); } catch (e) { reject(e); return; }
    const inst = new Runtime.OrbInstance(def, { ...config, background: transparent ? null : background }, state);
    if (state === 'intro') inst.sm.intro = 0;
    // pre-roll so states are fully blended at frame 0 (except intro)
    if (state !== 'intro') for (let i = 0; i < 90; i++) inst.update(1 / 60, null);
    renderer.draw(def, inst.u, size, size);

    const stream = canvas.captureStream(fps);
    const rec = new MediaRecorder(stream, { mimeType: fmt.mime, videoBitsPerSecond: Math.round(size * size * fps * 0.12) });
    const chunks = [];
    rec.ondataavailable = (e) => { if (e.data && e.data.size) chunks.push(e.data); };
    rec.onerror = (e) => reject(e.error || new Error('Recording failed'));
    rec.onstop = () => {
      renderer.dispose();
      resolve({ blob: new Blob(chunks, { type: fmt.mime.split(';')[0] }), ext: fmt.id });
    };

    let start = 0, last = 0, raf = 0;
    const loop = (now) => {
      if (!start) { start = now; last = now; }
      const dt = Math.min(0.05, (now - last) / 1000); last = now;
      const feats = live && live.active ? live.update(dt) : null;
      inst.update(dt, feats);
      renderer.draw(def, inst.u, size, size);
      const p = (now - start) / 1000 / duration;
      if (onProgress) onProgress(Math.min(1, p));
      if (p >= 1) { rec.stop(); stream.getTracks().forEach((t) => t.stop()); return; }
      raf = requestAnimationFrame(loop);
    };
    rec.start(250);
    raf = requestAnimationFrame(loop);
  });
}
